CREATE TABLE t1(w INT,x INT,y INT,z INT); WITH RECURSIVE c(w) AS (VALUES(1) UNION ALL SELECT w+1 FROM c WHERE w<100), v(w,x,y) AS (SELECT w,CASE WHEN w<2 THEN 0 WHEN w<4 THEN 1 WHEN w<8 THEN 2 WHEN w<16 THEN 3 WHEN w<32 THEN 4 WHEN w<64 THEN 5 ELSE 6 END,(w+1)*(w+1) FROM c) INSERT INTO t1 SELECT w,x,y,x+y FROM v; CREATE UNIQUE INDEX i1w ON t1(w); CREATE INDEX i1xy ON t1(x,y); CREATE INDEX i1zyx ON t1(z,y,x);